    fid = f"foe-{family}-{vid}"; parent = FAM_PARENT.get(family); first = parent is None
    if first: FAM_PARENT[family] = fid
    n = sum(1 for a in F if a.get("family") == family)
    fig(fid, g, f"{'an' if family[0] in 'aeiou' else 'a'} {family} ({vid})", h, kind, (people or words).format(h=h) + " " + text, f"one {family}: {desc}", list(pmust) + list(must), shaft=shaft, base=base,
        ref=None if first else parent, prio=prio if prio is not None else (2 if first else 6 + n * 0.1), name=name or f"{family.capitalize()}, {vid}", family=family, cls=family, boss=boss,
        tags=[family, vid, "foe", "monster"] + list(tags), srd=SRDF[family] + list(srd))
