# ------------------------------------------------------------------ the bestiary: one figure each
def beast(id, name, h, kind, design, desc, must=(), base=5, group="foe", srd=None, tags=(), prio=5.5, length=None, shaft=None, boss=False, top=None):
    fig(id, group, name, h, kind, design, desc, must, base=base, shaft=shaft, length=length, top=top, prio=prio, name=name[0].upper() + name[1:] if not name.startswith(("a ", "an ")) else name.split(" ", 1)[1].capitalize(),
        cls=id.split("-", 1)[1], boss=boss, tags=[id.split("-", 1)[1].replace("-", " ")] + list(tags) + (["monster"] if group in ("foe", "large") else ["animal"]), srd=srd if srd is not None else [id.split("-", 1)[1].replace("-", " ")])
QUAD = ["a tail, complete"]
# -- vermin and beasts that fight (staples first)
beast("foe-giant-rat", "a giant rat", 1.8, "quad", "A giant rat the size of a big dog: 1.8 ft tall at the back, about 3.5 ft long with its tail. Unmistakably a rat and not a dog, mouse or possum: a long pointed snout with two big cream front teeth, round ears, a hunched back, greasy dark grey-brown fur in a few big tufts, pink feet, and a THICK bare pink tail as thick as its leg curled forward close along its side on the ground.", "one giant rat on all fours with a thick bare tail", ["a thick bare tail"], prio=3, length=3.5, tags=["rat", "vermin", "dire rat"])
beast("foe-rat-swarm", "a swarm of rats", 1.2, "odd", "A SWARM OF RATS as ONE solid clump, 1.2 ft tall and 4 ft across: a single heaped mound of about twelve chunky dark grey-brown rats piled over each other, noses and thick pink tails poking out all round the edge, two rats rearing on top. One fused mass (no separate loose rats), its underside flat on the ground.", "one heaped mound of many rats fused into a single clump", ["many rats in one clump"], srd=["swarm of rats"], tags=["rats", "vermin", "swarm"])
beast("foe-giant-spider", "a giant spider", 2.5, "odd", "A giant spider 2.5 ft tall and 4 ft across its legs. A fat round abdomen and a smaller head-body, dark burgundy-brown with ochre bands and a cream skull-like mark on the abdomen, a cluster of pale eyes, two thick fangs. EIGHT legs, each drawn VERY THICK (as thick as a man's arm), short and strongly arched, all separately visible with background between them, all eight feet flat on the same level, tucked close so the whole spider fits in a 4-ft circle.", "one giant spider with eight thick legs standing", ["eight separate thick legs"], prio=3, tags=["spider", "giant wolf spider", "phase spider"], srd=["giant spider", "giant wolf spider", "phase spider", "spider"])
beast("foe-giant-bat", "a giant bat", 3.0, "odd", "A giant bat standing upright on the ground, 3 ft tall, its leathery WINGS FOLDED and wrapped close round its body like a cloak (two thick solid shapes, not spread, no thin membranes). A furry dark charcoal-brown body, a pug nose, big pointed upright ears, small fangs, two clawed feet flat on the ground and the two wing-claws resting on the ground in front.", "one big bat standing upright with its wings folded round its body", ["wings folded, not spread"], tags=["bat", "swarm of bats"], srd=["giant bat", "bat"])
beast("foe-giant-snake", "a giant snake", 3.0, "odd", "A giant constrictor snake COILED in a tight heap, 3 ft tall and 4 ft across: three thick stacked coils as thick as a man's thigh with the neck and wedge-shaped head rising from the middle to the top, mouth closed, tongue hidden. Moss-green scales with broad ochre diamond bands and a cream belly. One solid mass, its underside flat on the ground; nothing stretched out.", "one big snake coiled in a heap with its head raised", ["a coiled snake"], srd=["giant constrictor snake", "giant poisonous snake", "constrictor snake", "poisonous snake"], tags=["snake", "serpent"])
beast("foe-giant-centipede", "a giant centipede", 1.5, "odd", "A giant centipede 1.5 ft tall, curled in a tight S so it fits in a 4-ft circle: about ten thick glossy burgundy-brown armour segments, each with a pair of very thick, short ochre legs flat on the ground, a broad head with two thick curved fangs and two short thick feelers.", "one giant centipede with many thick short legs, curled", ["a long segmented body with many legs"], tags=["centipede", "vermin"])
beast("foe-giant-frog", "a giant frog", 2.5, "odd", "A giant frog squatting, 2.5 ft tall and 3.5 ft across: a wide flat head with a huge closed mouth and two bulging ochre eyes on top, a fat warty moss-green body with a cream throat, thick folded hind legs at its sides and two thick front legs planted in front, all four big webbed feet flat on the ground.", "one giant frog squatting", ["a squatting frog"], tags=["frog", "toad", "giant toad"], srd=["giant frog", "giant toad"])
beast("foe-crocodile", "a crocodile", 1.5, "quad", "A crocodile, low and long: 1.5 ft tall at the back, its thick tail CURVED round beside its body so the whole animal fits in a 4.5-ft circle. A long flat snout with thick cream teeth showing along the closed jaws, bumpy dark moss-green armour plates in big chunky rows, a cream belly, four short thick legs splayed with clawed feet flat on the ground.", "one crocodile on four short legs with its tail curved beside it", ["a long toothed snout"], length=4.5, tags=["alligator", "giant lizard"], srd=["crocodile", "giant lizard"])
beast("foe-wolf", "a grey wolf", 3.5, "quad", "A lean, rangy GREY timber wolf: about 2.75 ft tall at the shoulder, 3.5 ft to the tips of its ears with the head held up and forward, about 4.5 ft long. Unmistakably a wolf and not a dog, lion or hyena: a LONG narrow muzzle, tall pointed upright ears, long legs, a deep narrow chest, a level back. NO mane and NO neck ruff: the neck fur is short and lies flat. Light warm grey fur with a darker charcoal-grey saddle along the back and a cream muzzle, chest and legs (grey, not brown), painted as a few big smooth tufts. A long, thick, bushy tail with a dark tip, carried low, clear of the hind legs. Mouth closed. No collar.", "one wolf (a four-legged canine animal) standing on all four legs", QUAD + ["two ears"], prio=3, length=4.5, tags=["wolf"], srd=["wolf", "jackal"])
beast("foe-dire-wolf", "a dire wolf", 4.6, "quad", "A DIRE WOLF, a monstrous wolf as tall as a pony: 3.8 ft at the shoulder, 4.6 ft to the tips of its ears, a heavy body about 4.6 ft long. A wolf, not a bear or lion: a long heavy muzzle with thick fangs showing, tall pointed ears, very thick legs with huge paws, a hunched shoulder. Charcoal-black fur with ochre-grey flanks, painted as a few big chunky tufts (no mane), pale yellow eyes, a thick bushy tail carried low.", "one huge dark wolf standing on all four legs", QUAD, length=4.6, tags=["worg", "warg", "winter wolf"], srd=["dire wolf", "worg", "winter wolf"])
beast("foe-boar", "a wild boar", 3.0, "quad", "A wild boar: 3 ft tall at its high bristly shoulders, about 4.5 ft long. Unmistakably a boar and not a pig, bear or dog: a huge wedge-shaped head with a long snout ending in a flat pink disc, two thick curved cream TUSKS curling up from the lower jaw, small eyes, small upright ears, a ridge of thick dark bristles along the back drawn as one chunky crest, a heavy front and smaller hindquarters, short thick legs with hooves, a short thin tail. Dark charcoal-brown coat with ochre highlights.", "one wild boar with tusks standing on all four legs", ["two tusks"], prio=3, length=4.5, srd=["boar", "giant boar"])
# -- oozes, constructs, plants
beast("foe-slime-green", "a green slime", 3.0, "odd", "A gelatinous slime monster: a glossy, OPAQUE moss-green jelly mound 3 ft tall and 4 ft across, like a huge drop of thick pudding with a rounded top and a spreading skirt flat on the ground, two or three thick drips on its side. Sunk in its surface, clearly visible: a pale cream skull, two thick bones and a brass helmet. Solid and opaque (not transparent, not glowing), with broad soft highlights.", "one rounded green jelly blob with a skull and bones embedded in it", ["one single rounded blob"], prio=3, srd=["ochre jelly", "gray ooze", "green slime"], tags=["slime", "ooze", "jelly"])
beast("foe-gelatinous-cube", "a gelatinous cube", 5.0, "odd", "A gelatinous CUBE: a 5-ft cube of glossy, OPAQUE pale ochre-cream jelly with softly rounded edges and slightly bulging faces, sitting flat on the ground. Sunk in its faces, clearly visible: a whole pale cream skeleton arm and skull, a brass shield, a sword hilt and a few big coins. Solid and opaque (not transparent, not glowing), with broad soft highlights. It fits a 5-ft square exactly.", "one big cube of jelly with bones and a shield embedded in it", ["a cube shape"], prio=3, srd=["gelatinous cube"], tags=["ooze", "cube"])
beast("foe-black-ooze", "a black ooze", 1.5, "odd", "A black pudding ooze: a LOW, spreading, glossy, opaque charcoal-black puddle-mound 1.5 ft tall and 4.5 ft across with a lumpy rounded top, three thick blunt pseudopods reaching up a little, and thick burgundy highlights; half-dissolved in it, a pale cream skull and a rusty sword blade. Its underside flat on the ground.", "one low black blob with blunt lumps reaching up", ["one single low blob"], srd=["black pudding", "gray ooze"], tags=["ooze", "pudding", "puddle"])
beast("foe-mimic", "a mimic", 3.0, "odd", "A mimic: a treasure chest that is a monster, 3 ft tall with its lid open and 3 ft wide. A stout honey-brown wooden chest with thick brass bands and a big brass lock; the rim of the open lid and the rim of the box are lined with big thick cream FANGS, and one fat burgundy TONGUE lolls out over the front edge down to ground level. Two small yellow eyes on the inside of the lid. The chest's flat bottom sits on the ground level.", "one treasure chest with its lid open, lined with fangs, a big tongue hanging out", ["a chest with teeth and a tongue"], prio=3, srd=["mimic"])
beast("foe-animated-armour", "a suit of animated armour", 6.2, "hum", "An EMPTY suit of full plate armour walking by itself, 6.2 ft tall: warm grey steel with brass trim, a closed helmet with a dark empty visor slit (nothing inside), no skin anywhere, gaps of darkness at the joints. Its RIGHT gauntlet holds a broad bright SWORD upright in front of its shoulder; its LEFT arm holds a tall shield with a plain burgundy field close in front of its left side.", "one empty suit of plate armour with a closed helmet, holding one sword upright and one tall shield", ["exactly one sword", "a closed helmet, no face"], srd=["animated armor", "helmed horror"], tags=["construct", "living armour", "knight"])
beast("foe-gargoyle", "a gargoyle", 5.5, "hum", "A gargoyle, 5.5 ft tall, crouch-shouldered but standing on two clawed feet: a creature of grey-ochre STONE with a horned, snarling, fanged face, pointed ears, a muscular body with chiselled cracks, and two bat-like stone WINGS FOLDED tight against its back as two thick solid slabs (not spread). Clawed hands held up close in front of its chest; a thick short tail rests on the ground behind.", "one horned stone-skinned winged creature, wings folded, claws raised close", ["wings folded against the back", "looks made of stone"], srd=["gargoyle"], tags=["stone", "statue"])
beast("foe-scarecrow", "a scarecrow", 6.0, "hum", "A living scarecrow, 6 ft tall, standing on two thick straw-stuffed legs: a sack head with a stitched jagged grin and two dark eye holes under a battered wide-brimmed ochre hat, a patched burgundy coat stuffed fat with pale straw poking out in thick bunches at the cuffs, neck and ankles. Its arms are held a little forward at chest height, close, ending in big bundles of thick pale straw claws. No pole, no cross-beam.", "one straw-stuffed scarecrow in a hat and patched coat standing on its own legs", ["a sack face and straw"], tags=["construct", "harvest"], srd=["scarecrow"])
beast("foe-stone-golem", "a stone golem", 9.0, "hum", "A stone golem, 9 ft tall: a huge, heavy, roughly carved statue of a man made of grey-ochre granite blocks with deep chiselled seams, a small blunt head with two dark hollow eyes sunk between massive shoulders, a barrel chest, thick pillar legs and enormous square fists hanging at knee height close to its sides. Patches of moss on its shoulders. No weapon.", "one huge heavy stone statue-man with enormous fists", ["looks made of stone blocks"], base=10, group="large", srd=["stone golem", "clay golem"], tags=["golem", "construct", "statue"], boss=True)
beast("foe-iron-golem", "an iron golem", 10.0, "hum", "An iron golem, 10 ft tall: a towering armoured giant built of dark riveted iron plates with brass bands, a helmet-shaped head with a grille and no face, massive shoulders, thick piston-like limbs. Its RIGHT fist holds a huge broad iron SWORD standing point-down at ground level close beside its leg; its left fist hangs at its side.", "one towering giant of riveted iron plates with a helmet head, one huge sword point-down at its side", ["looks made of riveted metal plates"], base=10, group="large", srd=["iron golem", "shield guardian"], tags=["golem", "construct"], boss=True)
beast("foe-flesh-golem", "a flesh golem", 8.0, "hum", "A flesh golem, 8 ft tall: a hulking stitched-together man of mismatched grey-green and pale patches of skin joined by thick dark stitches and brass staples, a flat-topped head with a heavy brow and two brass bolts at the neck, one arm bigger than the other, huge hands hanging at knee height close to its sides, ragged burgundy trousers, bare feet.", "one hulking stitched-together man with bolts at the neck", ["visible stitches"], base=10, group="large", srd=["flesh golem"], tags=["golem", "construct", "monster"])
beast("foe-shambling-mound", "a shambling mound", 8.0, "odd", "A shambling mound, 8 ft tall: a walking heap of rotting vines, moss and leaves in the rough shape of a hunched giant with no neck: two thick trunk-like legs, two long thick vine-arms hanging forward to the ground, a lump for a head with two dim ochre eye-hollows. Dark moss green and brown, drawn as big chunky clumps of vegetation (no thin tendrils).", "one hulking heap of vines and moss shaped like a hunched giant", ["made of plants"], base=10, group="large", srd=["shambling mound"], tags=["plant", "swamp"])
beast("foe-treant", "a treant", 14.0, "odd", "A treant, a walking tree 14 ft tall: a thick gnarled honey-brown trunk with a wise old face formed in the bark (deep eye hollows, a nose-knot, a mossy beard), two thick root-legs spreading into the ground level, two heavy branch-arms bent down close to its sides ending in thick twig-fingers, and a crown of FIVE big solid chunky moss-green leaf clumps on top, like green clouds. Everything inside an 8.5-ft-wide cylinder.", "one walking tree with a face in its trunk, two branch arms and a leafy crown", ["a face in the trunk", "a leafy crown"], base=10, group="large", srd=["treant", "awakened tree"], tags=["tree", "ent", "plant"], boss=True)
beast("foe-awakened-shrub", "a twig blight", 3.0, "hum", "A twig blight, 3 ft tall: a spindly little walking bush shaped like a hunched child made of THICK dark thorny twigs (each as thick as a thumb, tightly bundled, not see-through), with a knot-head with two ochre eye-sparks (solid), a few big ochre leaves on its head and shoulders, and long thick twig-claws held close in front of its chest; two root-feet flat on the ground.", "one small humanoid made of bundled twigs with a few leaves", ["made of twigs"], srd=["awakened shrub", "twig blight", "needle blight"], tags=["plant", "blight"])
